"use client";

import { useEffect, useRef, useState } from "react";
import type { TemplateMode, TemplatePalette } from "./theme-presets";
import { themePresets } from "./theme-presets";
import { SkeuoThemeButton } from "../skeuo-theme-button";

export function TemplateCustomizer({
  palette,
  mode,
  onPaletteChange,
  onModeChange,
  onReset,
  templatesHref = "#",
}: {
  templatesHref?: string;
  palette: TemplatePalette;
  mode: TemplateMode;
  onPaletteChange: (value: TemplatePalette) => void;
  onModeChange: (value: TemplateMode) => void;
  onReset: () => void;
}) {
  const [open, setOpen] = useState(false);
  const panelRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    function onKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") setOpen(false);
    }
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [open]);

  return (
    <div ref={panelRef} className={`tpl-customizer ${open ? "is-open" : ""}`}>
      <button
        type="button"
        className="tpl-customizer-trigger"
        aria-label="Customize template"
        aria-expanded={open}
        aria-controls="tpl-customizer-panel"
        onClick={() => setOpen(!open)}
      >
        <span className="tpl-customizer-trigger-art" aria-hidden="true">
          <i />
          <i />
          <i />
        </span>
        <span>Customize</span>
        <span aria-hidden="true">{open ? "×" : "+"}</span>
      </button>
      <div
        id="tpl-customizer-panel"
        className="tpl-customizer-panel"
        hidden={!open}
      >
        <div className="tpl-customizer-heading">
          <div>
            <span>MAKE IT YOURS</span>
            <h2>Choose a world.</h2>
          </div>
          <button
            type="button"
            onClick={() => setOpen(false)}
            aria-label="Close customization"
          >
            ×
          </button>
        </div>
        <p>
          Each palette changes the canvas, surfaces, wells, typography, and
          accents together.
        </p>
        <div
          className="tpl-customizer-palettes"
          role="group"
          aria-label="Color palette"
        >
          {(Object.keys(themePresets) as TemplatePalette[]).map((key) => {
            const preset = themePresets[key];
            const colors = preset[mode];
            return (
              <button
                key={key}
                type="button"
                className="tpl-palette-option"
                aria-pressed={palette === key}
                onClick={() => onPaletteChange(key)}
              >
                <span
                  className="tpl-palette-specimen"
                  style={{
                    background: colors.background,
                    borderColor: colors.line,
                  }}
                  aria-hidden="true"
                >
                  <i
                    style={{
                      background: colors.panel,
                      borderColor: colors.line,
                    }}
                  />
                  <i style={{ background: colors.accent }} />
                  <i style={{ background: colors.secondary }} />
                </span>
                <span className="tpl-palette-copy">
                  <strong>{preset.name}</strong>
                  <small>{preset.description}</small>
                </span>
                <span className="tpl-palette-check" aria-hidden="true">
                  {palette === key ? "✓" : ""}
                </span>
              </button>
            );
          })}
        </div>
        <div className="tpl-customizer-mode">
          <span>APPEARANCE</span>
          <div className="tpl-customizer-mode-control">
            <span>{mode === "light" ? "Light mode" : "Dark mode"}</span>
            <SkeuoThemeButton
              theme={mode}
              onThemeChange={onModeChange}
              variant="round"
            />
          </div>
        </div>
        <div className="tpl-customizer-footer">
          <button type="button" onClick={onReset}>
            Reset this template
          </button>
          <a href={templatesHref}>All templates ↗</a>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState, type ReactNode } from "react";
import { TemplateCustomizer } from "./template-customizer";
import {
  themePresets,
  themeStyle,
  type TemplateMode,
  type TemplatePalette,
} from "./theme-presets";
import "./template-system.css";

export type TemplateOptions = {
  initialPalette?: TemplatePalette;
  initialMode?: TemplateMode;
  templatesHref?: string;
  soundControl?: ReactNode;
  syncPageBackground?: boolean;
};

export type TemplateState = {
  palette: TemplatePalette;
  mode: TemplateMode;
  setMode: (mode: TemplateMode) => void;
  language: "en" | "hi";
  setLanguage: (language: "en" | "hi") => void;
};

export function TemplateFrame({
  id,
  initialPalette = "ember",
  initialMode = "dark",
  syncPageBackground = false,
  templatesHref,
  children,
}: TemplateOptions & {
  id: string;
  children: (state: TemplateState) => ReactNode;
}) {
  const [palette, setPalette] = useState(initialPalette);
  const [mode, setMode] = useState(initialMode);
  const [language, setLanguage] = useState<"en" | "hi">("en");
  const [ready, setReady] = useState(false);
  useEffect(() => {
    let active = true;
    queueMicrotask(() => {
      if (!active) return;
      try {
        const saved = JSON.parse(
          localStorage.getItem(`skeuo-template-v3-${id}`) ?? "null",
        );
        if (saved?.palette && saved.palette in themePresets)
          setPalette(saved.palette);
        if (saved?.mode === "light" || saved?.mode === "dark")
          setMode(saved.mode);
        if (saved?.language === "hi") setLanguage("hi");
      } catch {
        /* Storage is optional for the preview. */
      }
      setReady(true);
    });
    return () => {
      active = false;
    };
  }, [id]);
  useEffect(() => {
    if (!ready) return;
    try {
      localStorage.setItem(
        `skeuo-template-v3-${id}`,
        JSON.stringify({ palette, mode, language }),
      );
    } catch {
      /* Private browsing can disable persistence. */
    }
  }, [id, palette, mode, language, ready]);
  useEffect(() => {
    if (!syncPageBackground) return;
    const html = document.documentElement;
    const body = document.body;
    const previous = [
      html.style.backgroundColor,
      body.style.backgroundColor,
      html.style.colorScheme,
    ];
    html.style.backgroundColor = body.style.backgroundColor =
      themePresets[palette][mode].background;
    html.style.colorScheme = mode;
    return () => {
      [
        html.style.backgroundColor,
        body.style.backgroundColor,
        html.style.colorScheme,
      ] = previous;
    };
  }, [palette, mode, syncPageBackground]);

  return (
    <div
      className={`sk-template sk-template-${id}`}
      data-sk-root=""
      data-theme={mode}
      data-palette={palette}
      style={themeStyle(palette, mode)}
    >
      <a className="sk-t-skip" href="#sk-template-main">
        Skip to content
      </a>
      <TemplateCustomizer
        templatesHref={templatesHref}
        palette={palette}
        mode={mode}
        onPaletteChange={setPalette}
        onModeChange={setMode}
        onReset={() => {
          setPalette(initialPalette);
          setMode(initialMode);
        }}
      />
      {children({ palette, mode, setMode, language, setLanguage })}
    </div>
  );
}

.sk-template {
  background: var(--tpl-bg);
  color: var(--tpl-ink);
  font-family: var(--font-geist-sans), Arial, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  min-height: 100dvh;
  isolation: isolate;
  color-scheme: light;
  --sk-font-sans: var(--font-geist-sans), Arial, sans-serif;
  --sk-surface-raised: var(--tpl-raised);
  --sk-key-base: var(--tpl-well);
  --sk-edge: var(--tpl-line);
  --sk-accent: var(--tpl-accent);
  --sk-accent-ink: var(--tpl-accent-ink);
  --sk-accent-bright: color-mix(in srgb, var(--tpl-accent) 90%, white);
  --sk-accent-base: color-mix(in srgb, var(--tpl-accent) 70%, black);
  --sk-accent-edge: color-mix(in srgb, var(--tpl-accent) 80%, black);
}
.sk-template[data-theme="dark"] {
  color-scheme: dark;
}
.sk-template *,
.sk-template *:before,
.sk-template *:after {
  box-sizing: border-box;
}
.sk-template :is(h1, h2, h3, p, figure, blockquote, dl, dd) {
  margin: 0;
}
.sk-template h1,
.sk-template h2,
.sk-template h3 {
  font-weight: 600;
  letter-spacing: -0.055em;
  line-height: 1.08;
  color: var(--tpl-ink);
}
.sk-template a {
  color: inherit;
  text-decoration: none;
}
.sk-template button,
.sk-template input,
.sk-template select {
  font-family: inherit;
}
.sk-template button,
.sk-template summary,
.sk-template select {
  cursor: pointer;
}
.sk-template button {
  color: inherit;
}
.sk-template a:focus-visible,
.sk-template button:focus-visible,
.sk-template summary:focus-visible,
.sk-template select:focus-visible,
.sk-template [tabindex]:focus-visible {
  outline: 2px solid var(--tpl-accent);
  outline-offset: 5px;
}
.sk-template ::selection {
  background: var(--tpl-accent);
  color: var(--tpl-accent-ink);
}
.sk-template svg {
  display: block;
  max-width: 100%;
}
.sk-template section[id] {
  scroll-margin-top: 32px;
}
.sk-template .sk-t-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}
.sk-t-skip {
  position: fixed;
  top: 10px;
  left: 10px;
  transform: translateY(-200%);
  z-index: 200;
  background: var(--tpl-accent);
  color: var(--tpl-accent-ink) !important;
  padding: 12px 20px;
  border-radius: 6px;
}
.sk-t-skip:focus {
  transform: none;
}
.sk-t-shell {
  width: min(1320px, calc(100% - 104px));
  margin-inline: auto;
}
.sk-t-section {
  padding-block: 112px;
}
.sk-t-eyebrow {
  font:
    400 10px/1.5 var(--font-geist-mono),
    monospace;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--tpl-muted);
  margin-bottom: 22px !important;
}
.sk-t-eyebrow:before {
  content: "";
  display: inline-block;
  width: 24px;
  height: 1px;
  background: var(--tpl-accent);
  margin: 0 12px 3px 0;
}
.sk-t-brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-size: 27px;
  line-height: 1;
  font-weight: 650;
  letter-spacing: -0.055em;
  white-space: nowrap;
}
.sk-t-brand b {
  color: var(--tpl-accent);
}
.sk-t-brand-symbol {
  width: 31px;
  height: 35px;
  display: grid;
  place-items: center;
  color: var(--tpl-accent);
  flex: none;
}
.sk-t-brand-symbol svg {
  width: 100%;
  height: 100%;
}
.sk-t-brand.is-glide .sk-t-brand-symbol {
  width: 27px;
  height: 27px;
  background: var(--tpl-ink);
  border-radius: 7px;
  color: var(--tpl-bg);
  padding: 5px;
}
.sk-t-icon-button {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  flex: none;
  border: 1px solid var(--tpl-line);
  border-radius: 7px;
  background: var(--tpl-panel);
  box-shadow:
    inset 0 1px var(--tpl-highlight),
    0 2px 0 var(--tpl-well);
  padding: 0;
}
.sk-t-icon-button:hover {
  background: var(--tpl-raised);
}
.sk-t-mobile-trigger {
  display: none;
}
.sk-t-text-link {
  display: inline-flex;
  align-items: center;
  gap: 13px;
  border: 0;
  border-bottom: 1px solid currentColor;
  padding: 5px 0;
  background: none;
  color: var(--tpl-ink);
  font-size: 13px;
  line-height: 1.6;
}
.sk-t-text-link:hover svg {
  transform: translateX(3px);
}
.sk-t-text-link svg {
  transition: transform 0.2s;
}
.sk-t-subtle {
  font-size: 12px;
  color: var(--tpl-muted);
}
.sk-t-status-dot {
  width: 6px;
  height: 6px;
  background: var(--tpl-accent);
  display: inline-block;
  border-radius: 50%;
  flex: none;
}
/* Reference-led landing layouts */
.sk-t-forma,
.sk-t-glide {
  overflow-x: clip;
}
.sk-t-landing-nav {
  position: relative;
  display: flex;
  align-items: center;
  min-height: 100px;
  border-bottom: 1px solid var(--tpl-line);
  gap: 34px;
  z-index: 10;
}
.sk-t-landing-nav nav {
  display: flex;
  align-items: center;
  gap: 27px;
  margin-left: auto;
  font-size: 12px;
  color: var(--tpl-muted);
}
.sk-t-landing-nav nav a:hover {
  color: var(--tpl-ink);
}
.sk-t-nav-actions {
  display: flex;
  align-items: center;
  gap: 12px;
}
.sk-t-nav-cta {
  display: flex;
  align-items: center;
  gap: 17px;
  padding: 11px 15px;
  background: var(--tpl-ink);
  color: var(--tpl-bg) !important;
  border-radius: 3px;
  font-size: 12px;
  white-space: nowrap;
}
.sk-t-nav-actions .sk-theme-key {
  width: 38px;
  height: 38px;
}
.sk-t-nav-actions .docs-theme-toggle {
  background: transparent;
  color: var(--tpl-muted);
  width: 32px;
  height: 38px;
  border: 0;
  display: grid;
  place-items: center;
}
.sk-t-forma-hero {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 40px;
  padding-top: 75px;
  align-items: center;
}
.sk-t-forma-hero h1 {
  font-size: clamp(60px, 7.7vw, 112px);
  letter-spacing: -0.065em;
  max-width: 680px;
  white-space: nowrap;
}
.sk-t-forma em {
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 400;
  color: var(--tpl-accent);
  letter-spacing: -0.055em;
}
.sk-t-forma-hero h1 em {
  font-size: 1.07em;
}
.sk-t-hero-description {
  font-size: 17px;
  line-height: 1.7;
  margin-top: 28px !important;
  color: var(--tpl-muted);
  letter-spacing: -0.02em;
  max-width: 480px;
}
.sk-t-hero-actions {
  display: flex;
  gap: 25px;
  align-items: center;
  flex-wrap: wrap;
  margin-top: 28px;
}
.sk-t-fine-print {
  font:
    9px/1.5 var(--font-geist-mono),
    monospace;
  color: var(--tpl-muted);
  margin-top: 22px !important;
  letter-spacing: 0.02em;
}
.sk-t-forma-object {
  position: relative;
  aspect-ratio: 1;
  width: min(100%, 460px);
  margin: 0 auto 32px;
  display: grid;
  place-items: center;
}
.sk-t-orbit-ticks {
  position: absolute;
  inset: 2%;
  border-radius: 50%;
  background: repeating-conic-gradient(
    from 0deg,
    var(--tpl-muted) 0deg 0.2deg,
    transparent 0.2deg 3deg
  );
  mask: radial-gradient(
    circle,
    transparent 68.8%,
    #000 69% 70.2%,
    transparent 70.4%
  );
  opacity: 0.55;
}
.sk-t-orbit-outer {
  position: absolute;
  inset: 6%;
  border-radius: 50%;
  background: conic-gradient(
    from -90deg,
    var(--tpl-accent) 0deg 72deg,
    var(--tpl-bg) 72deg 74deg,
    var(--tpl-secondary) 74deg 138deg,
    var(--tpl-bg) 138deg 140deg,
    var(--tpl-well) 140deg 262deg,
    var(--tpl-bg) 262deg 264deg,
    var(--tpl-accent) 264deg 314deg,
    var(--tpl-bg) 314deg 316deg,
    var(--tpl-secondary) 316deg 360deg
  );
  box-shadow:
    0 4px 18px var(--tpl-shadow),
    inset 0 1px 1px var(--tpl-highlight);
  mask: radial-gradient(circle, transparent 64%, #000 64.3%);
}
.sk-t-orbit-inner {
  position: absolute;
  inset: 13%;
  border: 1px solid var(--tpl-line);
  border-radius: 50%;
  background: radial-gradient(
    ellipse at 35% 20%,
    color-mix(in srgb, var(--tpl-panel) 70%, var(--tpl-bg)),
    var(--tpl-bg)
  );
  box-shadow:
    inset 0 4px 8px var(--tpl-shadow),
    0 1px 0 var(--tpl-highlight);
}
.sk-t-orbit-center {
  position: relative;
  display: flex;
  align-items: center;
  flex-direction: column;
  z-index: 1;
  line-height: 1.1;
}
.sk-t-orbit-center > span {
  font:
    8px var(--font-geist-mono),
    monospace;
  letter-spacing: 0.16em;
  color: var(--tpl-muted);
  margin-bottom: 15px;
}
.sk-t-orbit-center > strong {
  font-size: 37px;
  font-weight: 600;
  letter-spacing: -0.055em;
}
.sk-t-orbit-center > em {
  font-size: 47px;
  margin-top: 7px;
}
.sk-t-orbit-center > small {
  font-size: 11px;
  color: var(--tpl-muted);
  margin-top: 18px;
}
.sk-t-orbit-point {
  position: absolute;
  width: 9px;
  height: 9px;
  background: var(--tpl-accent);
  border: 2px solid var(--tpl-bg);
  outline: 1px solid var(--tpl-accent);
  border-radius: 50%;
  left: 18%;
  bottom: 18%;
  box-shadow: 0 0 15px color-mix(in srgb, var(--tpl-accent) 30%, transparent);
}
.sk-t-object-caption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -35px;
  display: flex;
  justify-content: space-between;
  font:
    8px/1.5 var(--font-geist-mono),
    monospace;
  color: var(--tpl-muted);
}
.sk-t-principles {
  grid-column: 1/-1;
  border-block: 1px solid var(--tpl-line);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  padding: 25px 0;
  margin-top: 32px;
}
.sk-t-principles > span {
  font:
    italic 24px/1.3 Georgia,
    serif;
}
.sk-t-principles > span:not(:first-child) {
  padding-left: 30px;
  border-left: 1px solid var(--tpl-line);
}
.sk-t-section-heading {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 70px;
  align-items: center;
  margin-bottom: 48px;
}
.sk-t-section-heading h2,
.sk-t-forma-possibilities h2,
.sk-t-forma-action h2 {
  font-size: clamp(46px, 5.7vw, 78px);
}
.sk-t-section-heading > p {
  font-size: 17px;
  line-height: 1.8;
  color: var(--tpl-muted);
  max-width: 460px;
}
.sk-t-product-explorer {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 238px;
  gap: 36px;
  align-items: center;
}
.sk-t-product-frame {
  border: 1px solid var(--tpl-line);
  border-radius: 6px;
  overflow: hidden;
  box-shadow: 0 15px 35px var(--tpl-shadow);
  background: var(--tpl-panel);
}
.sk-t-window-chrome {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 13px;
  border-bottom: 1px solid var(--tpl-line);
  color: var(--tpl-muted);
  min-height: 30px;
}
.sk-t-window-chrome > span {
  display: flex;
  gap: 4px;
}
.sk-t-window-chrome i {
  width: 5px;
  height: 5px;
  background: var(--tpl-muted);
  border-radius: 50%;
}
.sk-t-window-chrome i:first-child {
  background: var(--tpl-accent);
}
.sk-t-window-chrome small {
  font:
    8px var(--font-geist-mono),
    monospace;
}
.sk-t-dashboard-still {
  width: 100%;
  height: auto;
  display: block;
  font-family: Arial, sans-serif;
}
.sk-t-preview-caption {
  border-top: 1px solid var(--tpl-line);
  padding: 8px 12px;
  display: flex;
  justify-content: space-between;
  color: var(--tpl-muted);
  font:
    8px var(--font-geist-mono),
    monospace;
}
.sk-t-product-selector > button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  gap: 15px;
  border: 0;
  border-bottom: 1px solid var(--tpl-line);
  padding: 23px 0;
  background: none;
  text-align: left;
  font:
    italic 25px/1.2 Georgia,
    serif;
  color: var(--tpl-muted);
}
.sk-t-product-selector > button[aria-pressed="true"] {
  color: var(--tpl-accent);
  border-color: var(--tpl-accent);
}
.sk-t-product-selector > p {
  font-size: 13px;
  line-height: 1.7;
  color: var(--tpl-muted);
  margin-top: 22px;
  margin-bottom: 22px;
  min-height: 88px;
}
.sk-t-feature-notes {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin-top: 42px;
  border-top: 1px solid var(--tpl-line);
  padding-top: 30px;
}
.sk-t-feature-notes > div {
  padding-right: 30px;
}
.sk-t-feature-notes > div:not(:first-child) {
  padding-left: 30px;
  border-left: 1px solid var(--tpl-line);
}
.sk-t-feature-notes h3 {
  font-size: 20px;
  margin-bottom: 10px;
}
.sk-t-feature-notes p {
  font-size: 12px;
  line-height: 1.8;
  color: var(--tpl-muted);
}
.sk-t-forma-possibilities {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 100px;
  align-items: center;
}
.sk-t-forma-possibilities > div > p,
.sk-t-forma-action p {
  font-size: 16px;
  max-width: 390px;
  color: var(--tpl-muted);
  margin-top: 25px;
}
.sk-t-material-demo {
  max-width: 480px;
  margin-left: auto;
  padding: 30px !important;
}
.sk-t-material-demo-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.sk-t-material-demo-heading .sk-t-brand {
  font-size: 20px;
}
.sk-t-material-demo-heading > span {
  font:
    8px var(--font-geist-mono),
    monospace;
  color: var(--tpl-muted);
  letter-spacing: 0.1em;
}
.sk-t-material-greeting {
  margin-block: 45px;
}
.sk-t-material-greeting > span {
  font-size: 12px;
  color: var(--tpl-muted);
}
.sk-t-material-greeting > strong {
  display: block;
  font-size: 46px;
  line-height: 1.08;
  letter-spacing: -0.05em;
  font-weight: 500;
  margin-top: 10px;
}
.sk-t-material-switch {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 25px;
  border-top: 1px solid var(--tpl-line);
  padding-top: 20px;
}
.sk-t-material-switch strong {
  display: block;
  font-size: 12px;
}
.sk-t-material-switch small {
  display: block;
  font-size: 10px;
  color: var(--tpl-muted);
  margin-top: 4px;
}
.sk-t-material-lines {
  display: grid;
  gap: 9px;
  margin-top: 26px;
}
.sk-t-material-lines i {
  height: 6px;
  border-radius: 3px;
  background: var(--tpl-line);
  width: 100%;
  transition: width 0.25s;
}
.sk-t-material-lines i:nth-child(2n) {
  width: 75%;
}
.sk-t-material-lines.is-simple i:nth-last-child(-n + 2) {
  display: none;
}
.sk-t-questions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 100px;
  border-top: 1px solid var(--tpl-line);
}
.sk-t-questions h2 {
  font-size: clamp(40px, 4.3vw, 60px);
}
.sk-t-questions > div > p {
  font-size: 13px;
  line-height: 1.8;
  color: var(--tpl-muted);
  margin-top: 22px;
  max-width: 330px;
}
.sk-t-questions-list details {
  border-bottom: 1px solid var(--tpl-line);
}
.sk-t-questions-list summary {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 20px 0;
  list-style: none;
  font-size: 13px;
}
.sk-t-questions-list summary::-webkit-details-marker {
  display: none;
}
.sk-t-questions-list summary > span {
  font-size: 20px;
  color: var(--tpl-muted);
  transition: transform 0.2s;
}
.sk-t-questions-list details[open] summary > span {
  transform: rotate(45deg);
}
.sk-t-questions-list details > p {
  font-size: 12px;
  color: var(--tpl-muted);
  line-height: 1.8;
  padding: 0 25px 22px 0;
}
.sk-t-forma-action {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 40px;
  border-top: 1px solid var(--tpl-line);
}
.sk-t-tear-footer {
  width: 100%;
}
.sk-t-tear-footer .sk-t-brand {
  font-size: 24px;
}
/* Glide keeps the Handsfree rhythm, with a different object and generic product copy. */
.sk-t-glide {
  background-image:
    linear-gradient(
      to right,
      color-mix(in srgb, var(--tpl-line) 15%, transparent) 1px,
      transparent 1px
    ),
    linear-gradient(
      to bottom,
      color-mix(in srgb, var(--tpl-line) 15%, transparent) 1px,
      transparent 1px
    );
  background-size: 40px 40px;
  background-repeat: repeat-x;
  background-position: center top;
}
.sk-t-glide-hero {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 25px;
  padding-top: 65px;
  align-items: center;
}
.sk-t-glide-hero h1 {
  font-size: clamp(56px, 6.2vw, 88px);
  max-width: 720px;
  white-space: nowrap;
  letter-spacing: -0.06em;
}
.sk-t-glide :is(h1, h2) > span {
  color: var(--tpl-accent);
}
.sk-t-glide-object {
  width: 100%;
  margin-top: -30px;
  max-width: 550px;
  aspect-ratio: 1.07;
}
.sk-t-chrome-loop {
  width: 100%;
  height: 100%;
  animation: sk-t-float 8s ease-in-out infinite;
}
.sk-t-glide-principles {
  grid-column: 1/-1;
  display: grid;
  grid-template-columns: 1.1fr 1fr 1fr 1fr;
  border-block: 1px solid var(--tpl-line);
  padding-block: 24px;
  gap: 25px;
  margin-top: 15px;
  font-size: 11px;
  color: var(--tpl-muted);
}
.sk-t-glide-principles > span:not(:first-child) {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
}
.sk-t-glide-heading {
  margin-bottom: 45px;
}
.sk-t-glide h2 {
  font-size: clamp(40px, 4.8vw, 65px);
  line-height: 1.1;
}
.sk-t-glide-heading > p {
  margin-top: 25px;
  color: var(--tpl-muted);
  font-size: 14px;
  line-height: 1.8;
}
.sk-t-feature-rows {
  border-top: 1px solid var(--tpl-line);
}
.sk-t-feature-row {
  display: grid;
  grid-template-columns: 58px 1.1fr 1fr;
  gap: 24px;
  align-items: center;
  padding-block: 35px;
  border-bottom: 1px solid var(--tpl-line);
}
.sk-t-feature-icon {
  width: 48px;
  height: 48px;
  border: 1px solid var(--tpl-line);
  background: var(--tpl-panel);
  border-radius: 12px;
  display: grid;
  place-items: center;
  box-shadow:
    inset 0 1px var(--tpl-highlight),
    0 3px 0 var(--tpl-well);
}
.sk-t-feature-row h3 {
  font-size: 24px;
  margin-bottom: 10px;
}
.sk-t-feature-row p {
  color: var(--tpl-muted);
  font-size: 12px;
  line-height: 1.8;
}
.sk-t-feature-row > p {
  max-width: 390px;
}
.sk-t-bento {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  grid-template-rows: repeat(2, minmax(260px, auto));
  gap: 14px;
}
.sk-t-bento-card {
  position: relative;
  background: var(--tpl-panel);
  border: 1px solid var(--tpl-line);
  border-radius: 16px;
  padding: 30px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 35px;
  box-shadow:
    inset 0 1px var(--tpl-highlight),
    0 3px 0 var(--tpl-well);
  transition:
    border-color 0.3s,
    transform 0.3s;
}
.sk-t-bento-card:before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(
    340px circle at var(--glow-x, 50%) var(--glow-y, 50%),
    color-mix(in srgb, var(--tpl-accent) 12%, transparent),
    transparent 70%
  );
  transition: opacity 0.3s;
}
.sk-t-bento-card:hover:before {
  opacity: 1;
}
.sk-t-bento-card:hover {
  border-color: color-mix(in srgb, var(--tpl-accent) 50%, var(--tpl-line));
  transform: translateY(-2px);
}
.sk-t-bento-card > * {
  position: relative;
}
.sk-t-bento-card h3 {
  font-size: 25px;
  margin-bottom: 12px;
}
.sk-t-bento-card p {
  color: var(--tpl-muted);
  font-size: 13px;
  line-height: 1.8;
}
.sk-t-bento-main {
  grid-column: span 2;
  grid-row: span 2;
  justify-content: center;
  gap: 55px;
}
.sk-t-bento-keys,
.sk-t-bento-palette {
  grid-column: span 2;
}
.sk-t-bento-browser {
  margin: 5px -5px 0;
  border: 1px solid var(--tpl-line);
  border-radius: 10px;
  background: var(--tpl-bg);
  box-shadow: 0 18px 25px var(--tpl-shadow);
  transform: perspective(900px) rotateY(-4deg) rotateX(3deg);
  transition: transform 0.5s;
}
.sk-t-bento-main:hover .sk-t-bento-browser {
  transform: none;
}
.sk-t-bento-browser > div:first-child {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 11px 13px;
  border-bottom: 1px solid var(--tpl-line);
}
.sk-t-bento-browser i {
  width: 5px;
  height: 5px;
  background: var(--tpl-line);
  border-radius: 50%;
}
.sk-t-bento-browser > div:first-child > span {
  margin: auto;
  font-size: 8px;
  color: var(--tpl-muted);
}
.sk-t-bento-browser-body {
  padding: 30px 22px;
}
.sk-t-bento-mini-label {
  font:
    7px var(--font-geist-mono),
    monospace;
  letter-spacing: 0.12em;
  color: var(--tpl-muted);
}
.sk-t-bento-browser-body > strong {
  display: block;
  font-size: 32px;
  letter-spacing: -0.05em;
  font-weight: 500;
  margin-top: 14px;
}
.sk-t-bento-browser-body > p {
  font-size: 10px;
  margin-top: 5px;
  margin-bottom: 20px;
}
.sk-t-bento-browser-body > div {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 0;
  border-top: 1px solid var(--tpl-line);
  font-size: 10px;
}
.sk-t-bento-browser-body > div > span:last-child {
  margin-left: auto;
  color: var(--tpl-muted);
}
.sk-t-mini-check {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  background: var(--tpl-panel);
  color: var(--tpl-accent);
  border-radius: 6px;
}
.sk-t-key-art {
  display: flex;
  gap: 20px;
  justify-content: center;
  transform: rotate(-6deg);
  padding-top: 12px;
}
.sk-t-key-art .sk-tech-key {
  width: 84px;
}
.sk-t-key-art .sk-tech-key:nth-child(2) {
  transform: translateY(13px) rotate(12deg);
}
.sk-t-palette-art {
  display: flex;
  gap: 9px;
  align-items: center;
  margin-top: 10px;
}
.sk-t-palette-art i {
  width: 45px;
  height: 45px;
  border-radius: 50%;
  background: var(--tpl-ink);
  border: 3px solid var(--tpl-panel);
  outline: 1px solid var(--tpl-line);
  box-shadow: 0 4px 6px var(--tpl-shadow);
}
.sk-t-palette-art i:nth-child(2) {
  background: var(--tpl-accent);
  margin-left: -20px;
}
.sk-t-palette-art i:nth-child(3) {
  background: var(--tpl-raised);
  margin-left: -20px;
}
.sk-t-palette-art > span {
  font:
    italic 45px Georgia,
    serif;
  margin-left: auto;
  color: var(--tpl-muted);
}
.sk-t-glide-steps {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 100px;
}
.sk-t-glide-steps > div:first-child > p {
  color: var(--tpl-muted);
  font-size: 13px;
  line-height: 1.8;
  margin-top: 25px;
  max-width: 330px;
}
.sk-t-glide-steps > div:last-child > div {
  display: flex;
  gap: 20px;
  border-bottom: 1px solid var(--tpl-line);
  padding: 25px 0;
}
.sk-t-glide-steps > div:last-child > div:first-child {
  padding-top: 0;
}
.sk-t-glide-steps > div:last-child > div > span {
  width: 30px;
  height: 30px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  flex: none;
  background: var(--tpl-accent);
  color: var(--tpl-accent-ink);
  font:
    10px var(--font-geist-mono),
    monospace;
}
.sk-t-glide-steps h3 {
  font-size: 19px;
}
.sk-t-glide-steps > div:last-child p {
  font-size: 12px;
  line-height: 1.8;
  color: var(--tpl-muted);
  margin-top: 10px;
}
.sk-t-stories {
  overflow: hidden;
  border-top: 1px solid var(--tpl-line);
}
.sk-t-story-heading {
  text-align: center;
  margin-bottom: 50px;
  padding-inline: 20px;
}
.sk-t-story-heading > p {
  font-size: 12px;
  color: var(--tpl-muted);
  margin-top: 22px;
}
.sk-t-story-heading > button {
  font-size: 10px;
  margin-top: 12px;
  color: var(--tpl-muted);
}
.sk-t-story-marquees {
  width: min(1400px, 100%);
  margin: auto;
  mask-image: linear-gradient(90deg, transparent, #000 8% 92%, transparent);
}
.sk-t-story-row {
  display: flex;
  gap: 16px;
  margin-bottom: 16px;
  width: max-content;
}
.sk-t-story-set {
  display: flex;
  gap: 16px;
  animation: sk-t-marquee 48s linear infinite;
}
.sk-t-story-row.row-1 .sk-t-story-set {
  animation-direction: reverse;
  animation-duration: 55s;
}
.sk-t-story-marquees:is(:hover, :focus-within, .is-paused) .sk-t-story-set {
  animation-play-state: paused;
}
.sk-t-story-set figure {
  width: 390px;
  padding: 30px;
  background: var(--tpl-panel);
  border: 1px solid var(--tpl-line);
  border-radius: 12px;
  box-shadow: inset 0 1px var(--tpl-highlight);
}
.sk-t-story-set blockquote {
  font-size: 17px;
  letter-spacing: -0.025em;
  line-height: 1.6;
  min-height: 110px;
}
.sk-t-story-set figcaption {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 25px;
}
.sk-t-story-set figcaption strong {
  display: block;
  font-size: 11px;
}
.sk-t-story-set figcaption div > span {
  display: block;
  color: var(--tpl-muted);
  font-size: 10px;
}
.sk-t-glide-action {
  text-align: center;
  padding-top: 50px;
}
.sk-t-glide-action h2 {
  font-size: clamp(42px, 5vw, 72px);
}
.sk-t-glide-action p {
  color: var(--tpl-muted);
  margin: 25px 0 28px;
}
.sk-t-glide-footer {
  border-top: 1px solid var(--tpl-line);
  padding-top: 30px;
}
.sk-t-glide-footer > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  font-size: 10px;
  color: var(--tpl-muted);
}
.sk-t-glide-footer > div:first-child .sk-t-text-link {
  font-size: 10px;
}
.sk-t-glide-footer .sk-t-brand {
  font-size: 22px;
  color: var(--tpl-ink);
}
.sk-t-glide-wordmark {
  font-size: clamp(130px, 25vw, 350px);
  line-height: 1.12;
  font-weight: 600;
  letter-spacing: -0.085em;
  margin: 20px 0 30px !important;
  text-align: center;
}
.sk-t-glide-wordmark > span {
  color: var(--tpl-accent);
}
.sk-t-glide-footer > div:last-child {
  border-top: 1px solid var(--tpl-line);
  padding-block: 25px;
  font-size: 9px;
}
.sk-t-glide-footer nav {
  display: flex;
  gap: 20px;
}
/* Dashboard layouts: a flush personal workspace and an inset team workspace. */
.sk-t-dashboard {
  --sidebar-width: 232px;
  display: grid;
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr);
  min-height: 100dvh;
}
.sk-t-sidebar {
  position: sticky;
  top: 0;
  height: 100dvh;
  display: flex;
  flex-direction: column;
  padding: 24px 15px 14px;
  border-right: 1px solid var(--tpl-line);
  background: color-mix(in srgb, var(--tpl-panel) 22%, var(--tpl-bg));
  min-width: 0;
  z-index: 30;
}
.sk-t-sidebar-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 40px;
  padding-inline: 4px;
}
.sk-t-sidebar-heading .sk-t-brand {
  font-size: 23px;
}
.sk-t-sidebar-heading .sk-t-brand-symbol {
  width: 28px;
}
.sk-t-sidebar-heading .sk-t-icon-button {
  width: 29px;
  height: 29px;
  border: 0;
  box-shadow: none;
  background: none;
  color: var(--tpl-muted);
}
.sk-t-sidebar-heading .sk-t-icon-button > svg {
  width: 18px;
}
.sk-t-sidebar-nav {
  display: grid;
  gap: 26px;
  overflow-y: auto;
  min-height: 0;
  flex: 1;
  align-content: start;
}
.sk-t-nav-group > p {
  color: var(--tpl-muted);
  font-size: 10px;
  font-weight: 500;
  padding-left: 13px;
  margin-bottom: 10px;
}
.sk-t-nav-group > a {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 45px;
  padding: 10px 13px;
  border-radius: 7px;
  color: var(--tpl-muted);
  font-size: 12px;
  transition:
    background 0.18s,
    color 0.18s;
}
.sk-t-nav-group > a[aria-current="location"] {
  background: var(--tpl-panel);
  color: var(--tpl-accent);
  box-shadow:
    inset 0 1px var(--tpl-highlight),
    0 1px 2px var(--tpl-shadow);
  font-weight: 600;
}
.sk-t-nav-group > a[aria-current="location"]:after {
  content: "";
  width: 5px;
  height: 5px;
  margin-left: auto;
  background: var(--tpl-accent);
  border-radius: 50%;
}
.sk-t-nav-group > a:hover {
  background: var(--tpl-panel);
  color: var(--tpl-ink);
}
.sk-t-nav-group > a > svg {
  flex: none;
  width: 18px;
}
.sk-t-nav-group > a > small {
  margin-left: auto;
  font-size: 10px;
  background: var(--tpl-well);
  border-radius: 5px;
  padding: 1px 6px;
}
.sk-t-sidebar-bottom {
  position: relative;
  margin-top: auto;
  padding-top: 18px;
  flex: none;
}
.sk-t-sidebar-help {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 13px;
  color: var(--tpl-muted) !important;
  font-size: 11px;
  margin-bottom: 18px;
}
.sk-t-sidebar-help > svg {
  width: 17px;
  flex: none;
}
.sk-t-profile-button {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  text-align: left;
  border: 1px solid var(--tpl-line);
  background: var(--tpl-panel);
  border-radius: 9px;
  padding: 10px;
  box-shadow:
    inset 0 1px var(--tpl-highlight),
    0 2px 0 var(--tpl-well);
  min-height: 62px;
}
.sk-t-avatar {
  width: 33px;
  height: 33px;
  border-radius: 50%;
  background: var(--tpl-well);
  color: var(--tpl-accent);
  border: 1px solid var(--tpl-line);
  display: inline-grid;
  place-items: center;
  flex: none;
  font-size: 10px;
  font-weight: 600;
}
.sk-t-profile-button strong {
  display: block;
  font-size: 11px;
  font-weight: 550;
}
.sk-t-profile-button small {
  display: block;
  font-size: 9px;
  color: var(--tpl-muted);
  margin-top: 2px;
}
.sk-t-profile-button > span:last-child {
  margin-left: auto;
  color: var(--tpl-muted);
}
.sk-t-profile-panel {
  margin-bottom: 10px;
  padding: 16px;
  border: 1px solid var(--tpl-line);
  background: var(--tpl-panel);
  border-radius: 9px;
  width: 100%;
  max-height: 45dvh;
  overflow-y: auto;
  box-shadow: 0 4px 15px var(--tpl-shadow);
}
.sk-t-profile-panel > strong {
  font-size: 12px;
