  padding-bottom: 12px;
  border-bottom: 1px solid var(--tpl-line);
}
.sk-t-profile-panel > label {
  display: grid;
  gap: 8px;
  color: var(--tpl-muted);
  font-size: 10px;
  margin-top: 12px;
}
.sk-t-profile-panel > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 10px;
  gap: 10px;
  margin-top: 15px;
}
.sk-t-profile-panel .sk-theme-key {
  width: 34px;
  height: 34px;
}
.sk-t-profile-panel .docs-theme-toggle {
  width: 34px;
  height: 34px;
  background: var(--tpl-raised);
  border: 1px solid var(--tpl-line);
  color: var(--tpl-ink);
  display: grid;
  place-items: center;
  border-radius: 6px;
}
.sk-t-dashboard select {
  border: 1px solid var(--tpl-line);
  background: var(--tpl-raised);
  color: var(--tpl-ink);
  font-size: 10px;
  min-height: 34px;
  padding: 6px 25px 6px 10px;
  border-radius: 6px;
  max-width: 100%;
}
.sk-t-workspace-body {
  min-width: 0;
}
.sk-t-topbar {
  min-height: 81px;
  border-bottom: 1px solid var(--tpl-line);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 16px 30px;
  background: var(--tpl-bg);
}
.sk-t-topbar-heading {
  display: flex;
  align-items: center;
  gap: 12px;
}
.sk-t-topbar-heading > div > span {
  display: block;
  font-size: 9px;
  color: var(--tpl-muted);
  margin-bottom: 2px;
}
.sk-t-topbar-heading strong {
  display: block;
  font-size: 14px;
  font-weight: 550;
}
.sk-t-topbar-controls {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}
.sk-t-topbar-controls > .sk-theme-key {
  width: 36px;
  height: 36px;
}
.sk-t-segment {
  display: flex;
  gap: 2px;
  padding: 3px;
  background: var(--tpl-well);
  border: 1px solid var(--tpl-line);
  border-radius: 8px;
  box-shadow: inset 0 2px 3px var(--tpl-shadow);
}
.sk-t-segment > button {
  border: 1px solid transparent;
  padding: 5px 12px;
  border-radius: 5px;
  background: none;
  font-size: 10px;
  min-height: 28px;
  color: var(--tpl-muted);
}
.sk-t-segment > button[aria-pressed="true"] {
  background: var(--tpl-panel);
  color: var(--tpl-ink);
  border-color: var(--tpl-line);
  box-shadow:
    inset 0 1px var(--tpl-highlight),
    0 1px 3px var(--tpl-shadow);
}
.sk-t-dashboard-content {
  width: 100%;
  max-width: 1500px;
  margin: auto;
  padding: 38px 40px 0;
}
.sk-t-dashboard-intro {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 30px;
  margin-bottom: 30px;
}
.sk-t-dashboard-intro .sk-t-eyebrow {
  margin-bottom: 10px !important;
  font-size: 9px;
}
.sk-t-dashboard-intro h1 {
  font-size: clamp(28px, 2.8vw, 43px);
  line-height: 1.15;
}
.sk-t-dashboard-intro > div > p:last-child {
  font-size: 12px;
  color: var(--tpl-muted);
  margin-top: 14px;
}
.sk-t-update {
  position: relative;
  font-size: 9px;
  color: var(--tpl-muted);
  border-left: 1px solid var(--tpl-line);
  padding-left: 20px;
  white-space: nowrap;
}
.sk-t-update > .sk-t-status-dot {
  width: 4px;
  height: 4px;
  margin-right: 7px;
}
.sk-t-update > strong {
  display: block;
  font-weight: 400;
  color: var(--tpl-ink);
  font-size: 10px;
  margin-top: 5px;
}
.sk-t-metric-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  border: 1px solid var(--tpl-line);
  border-radius: 12px;
  background: var(--tpl-panel);
  overflow: hidden;
  margin-bottom: 20px;
  box-shadow:
    inset 0 1px var(--tpl-highlight),
    0 2px 0 var(--tpl-well);
}
.sk-t-metric-strip > div {
  padding: 23px;
  border-right: 1px solid var(--tpl-line);
  min-width: 0;
}
.sk-t-metric-strip > div:last-child {
  border: 0;
}
.sk-t-metric-strip span {
  display: block;
  font-size: 10px;
  color: var(--tpl-muted);
}
.sk-t-metric-strip strong {
  display: block;
  font-size: clamp(23px, 2.2vw, 34px);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.05em;
  margin-top: 18px;
  margin-bottom: 12px;
  white-space: nowrap;
}
.sk-t-metric-strip > div:first-child strong {
  color: var(--tpl-accent);
}
.sk-t-metric-strip small {
  display: block;
  color: var(--tpl-muted);
  font-size: 9px;
}
.sk-t-panel {
  border: 1px solid var(--tpl-line);
  background: var(--tpl-panel);
  border-radius: 12px;
  padding: 24px;
  box-shadow:
    inset 0 1px var(--tpl-highlight),
    0 2px 0 var(--tpl-well);
  min-width: 0;
}
.sk-t-panel-heading {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 25px;
  margin-bottom: 22px;
}
.sk-t-panel h2 {
  font-size: 17px;
  letter-spacing: -0.035em;
  line-height: 1.3;
}
.sk-t-panel-heading .sk-t-eyebrow {
  font-size: 8px;
  margin-bottom: 5px !important;
}
.sk-t-panel-heading .sk-t-eyebrow:before {
  display: none;
}
.sk-t-panel-heading p:not(.sk-t-eyebrow) {
  color: var(--tpl-muted);
  font-size: 10px;
  margin-top: 7px;
}
.sk-t-chart-summary {
  padding: 8px 12px;
  border-radius: 6px;
  background: var(--tpl-well);
  text-align: right;
}
.sk-t-chart-summary span {
  font-size: 8px;
  color: var(--tpl-muted);
  display: block;
}
.sk-t-chart-summary strong {
  font-size: 13px;
  font-weight: 550;
  display: block;
  margin-top: 2px;
}
.sk-t-chart {
  display: flex;
  gap: 14px;
  height: 270px;
  padding-top: 18px;
}
.sk-t-chart-y {
  width: 27px;
  flex: none;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding-bottom: 30px;
  font-size: 9px;
  color: var(--tpl-muted);
  text-align: right;
}
.sk-t-chart-plot {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
}
.sk-t-chart-plot > svg {
  width: 100%;
  height: calc(100% - 30px);
