  gap: 13px;
  align-items: center;
  padding-block: 15px;
  border-bottom: 1px solid var(--tpl-line);
}
.sk-t-app-row:last-child {
  border: 0;
  padding-bottom: 0;
}
.sk-t-app-rank {
  width: 27px;
  height: 27px;
  display: grid;
  place-items: center;
