  align-items: center;
  justify-content: center;
  flex-direction: column;
}
.sk-t-focus-ring strong {
  font-size: 38px;
  font-weight: 500;
  letter-spacing: -0.06em;
  line-height: 1.2;
}
.sk-t-focus-ring strong > span {
  font-size: 18px;
  letter-spacing: -0.02em;
}
.sk-t-focus-ring small {
  font-size: 9px;
  color: var(--tpl-muted);
  margin-top: 3px;
}
.sk-t-focus-details > div {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding: 10px 0;
  border-top: 1px solid var(--tpl-line);
