.sk-t-focus-details dt {
  color: var(--tpl-muted);
  font-size: 10px;
}
.sk-t-focus-details dd {
  font-weight: 550;
  font-variant-numeric: tabular-nums;
}
.sk-t-export-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-top: 30px;
  padding-bottom: 10px;
}
.sk-t-export-row p {
  font-size: 11px;
  color: var(--tpl-muted);
}
.sk-t-dashboard-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-top: 32px;
