}
.sk-t-dashboard.is-compact .sk-t-sidebar-label {
  display: none;
}
.sk-t-dashboard.is-compact .sk-t-sidebar-heading {
  flex-direction: column;
  margin-bottom: 25px;
  padding: 0;
  gap: 16px;
}
.sk-t-dashboard.is-compact .sk-t-sidebar {
  padding-inline: 12px;
}
.sk-t-dashboard.is-compact .sk-t-sidebar-heading .sk-t-brand-symbol {
  width: 30px;
}
.sk-t-dashboard.is-compact .sk-t-nav-group > a {
  padding: 10px;
  justify-content: center;
}
.sk-t-dashboard.is-compact .sk-t-nav-group > a[aria-current="location"]:after {
  display: none;
}
.sk-t-dashboard.is-compact .sk-t-sidebar-help {
  padding-inline: 0;
  justify-content: center;
}
.sk-t-dashboard.is-compact .sk-t-profile-button {
  padding: 7px;
  justify-content: center;
  min-height: 49px;
}
.sk-t-dashboard.is-compact .sk-t-workspace-switch {
  justify-content: center;
  padding: 5px;
}
.sk-t-dashboard.is-compact .sk-t-pinned-projects > button {
  justify-content: center;
}
.sk-t-workspace-switch {
  display: flex;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--tpl-line);
  padding: 10px;
  border-radius: 8px;
  margin-bottom: 27px;
}
.sk-t-square-avatar {
  width: 31px;
  height: 31px;
  display: grid;
  place-items: center;
  border-radius: 6px;
  background: var(--tpl-accent);
  color: var(--tpl-accent-ink);
  font-size: 13px;
  font-weight: 600;
  flex: none;
}
.sk-t-workspace-switch strong {
  font-size: 11px;
  display: block;
  font-weight: 550;
}
.sk-t-workspace-switch small {
  font-size: 9px;
  color: var(--tpl-muted);
  display: block;
  margin-top: 2px;
}
.sk-t-dashboard-workspace .sk-t-sidebar-heading {
  margin-bottom: 24px;
}
.sk-t-dashboard-workspace .sk-t-sidebar {
  background: var(--tpl-bg);
}
.sk-t-dashboard-workspace .sk-t-workspace-body {
  background: color-mix(in srgb, var(--tpl-well) 25%, var(--tpl-bg));
  padding: 12px 12px 0 0;
}
.sk-t-dashboard-workspace .sk-t-topbar {
  border: 1px solid var(--tpl-line);
  border-radius: 12px 12px 0 0;
  padding: 15px 25px;
}
.sk-t-dashboard-workspace .sk-t-dashboard-content {
  padding: 32px 25px 0;
  background: var(--tpl-bg);
  border-inline: 1px solid var(--tpl-line);
  max-width: none;
  min-height: calc(100dvh - 93px);
}
.sk-t-dashboard-workspace .sk-t-panel {
  background: var(--tpl-raised);
}
.sk-t-top-search {
  position: relative;
  max-width: 240px;
}
.sk-t-top-search > svg {
  position: absolute;
  left: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--tpl-muted);
  pointer-events: none;
}
.sk-t-top-search input {
  padding: 8px 12px 8px 35px;
  font-size: 10px;
  width: 100%;
  min-height: 34px;
}
.sk-t-date-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  color: var(--tpl-muted);
  white-space: nowrap;
}
.sk-t-workspace-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 15px;
  margin-bottom: 20px;
}
.sk-t-workspace-metric {
  padding: 20px;
}
.sk-t-workspace-metric > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--tpl-muted);
  font-size: 11px;
  gap: 10px;
}
.sk-t-workspace-metric > strong {
  display: block;
  font-size: 32px;
  line-height: 1.2;
  font-weight: 550;
  letter-spacing: -0.055em;
  margin: 20px 0 15px;
}
.sk-t-workspace-metric > p {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  font-size: 8px;
  color: var(--tpl-muted);
}
.sk-t-workspace-metric > p > b {
  font-size: 9px;
  font-weight: 500;
  color: var(--tpl-accent);
  padding: 2px 5px;
  background: var(--tpl-panel);
  border-radius: 4px;
}
.sk-t-workspace-charts {
  display: grid;
  grid-template-columns: minmax(0, 1.7fr) minmax(230px, 1fr);
  gap: 20px;
  margin-bottom: 20px;
}
.sk-t-revenue-total {
  display: flex;
  align-items: baseline;
  gap: 17px;
}
.sk-t-revenue-total > strong {
  font-size: 30px;
  font-weight: 550;
  letter-spacing: -0.05em;
}
.sk-t-revenue-total > span {
  font-size: 9px;
  color: var(--tpl-muted);
}
.sk-t-workspace-charts .sk-t-chart {
  height: 230px;
}
.sk-t-goal-panel > p {
  font-size: 10px;
  color: var(--tpl-muted);
  margin-top: 9px;
}
.sk-t-goal-dial {
  position: relative;
  max-width: 230px;
  margin: 28px auto 5px;
}
.sk-t-goal-dial > div {
  position: absolute;
  inset: 30% 0 0;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
}
.sk-t-goal-dial strong {
  font-size: 45px;
  line-height: 1.1;
  letter-spacing: -0.05em;
  font-weight: 550;
}
.sk-t-goal-dial strong span {
  font-size: 23px;
}
.sk-t-goal-dial small {
  font-size: 9px;
  color: var(--tpl-muted);
  margin-top: 6px;
}
.sk-t-goal-summary {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  border-top: 1px solid var(--tpl-line);
  padding-top: 20px;
  margin-top: 25px;
}
.sk-t-goal-summary span {
  display: block;
  color: var(--tpl-muted);
  font-size: 9px;
}
.sk-t-goal-summary strong {
  font-size: 17px;
  font-weight: 550;
  letter-spacing: -0.03em;
  display: block;
  margin-top: 5px;
}
.sk-t-table-scroll {
  overflow-x: auto;
  scrollbar-width: thin;
  max-width: 100%;
  border-top: 1px solid var(--tpl-line);
}
.sk-t-table-scroll table {
  border-collapse: collapse;
  width: 100%;
  min-width: 670px;
  text-align: left;
}
.sk-t-table-scroll th {
  padding: 14px 10px;
  font-size: 9px;
  font-weight: 500;
  color: var(--tpl-muted);
  border-bottom: 1px solid var(--tpl-line);
}
.sk-t-table-scroll td {
  padding: 14px 10px;
  border-bottom: 1px solid var(--tpl-line);
  font-size: 10px;
  white-space: nowrap;
}
.sk-t-table-scroll tbody tr:last-child td {
  border-bottom: 0;
}
.sk-t-table-scroll tbody tr:hover {
  background: var(--tpl-bg);
}
.sk-t-table-scroll td > strong {
  font-size: 10px;
  font-weight: 550;
  display: block;
}
.sk-t-table-scroll td > small {
  display: block;
  font-size: 8px;
  color: var(--tpl-muted);
  margin-top: 3px;
}
.sk-t-table-person {
  display: flex;
  align-items: center;
  gap: 10px;
}
.sk-t-table-person .sk-t-avatar {
  width: 27px;
  height: 27px;
  font-size: 8px;
  border-radius: 7px;
}
.sk-t-amount {
  font-weight: 550;
  font-variant-numeric: tabular-nums;
}
.sk-t-order-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  border: 1px solid var(--tpl-line);
  border-radius: 5px;
  padding: 3px 7px;
  font-size: 9px;
}
.sk-t-order-status > i {
  width: 4px;
  height: 4px;
  background: currentColor;
  border-radius: 50%;
}
.sk-t-order-status[data-status="Paid"] {
  color: var(--tpl-accent);
  background: var(--tpl-panel);
}
.sk-t-order-status[data-status="Pending"] {
  color: var(--tpl-muted);
}
.sk-t-table-footer {
  font-size: 9px;
  color: var(--tpl-muted);
  padding-top: 16px;
  border-top: 1px solid var(--tpl-line);
}
.sk-t-empty {
  text-align: center;
  padding: 35px;
  color: var(--tpl-muted);
  font-size: 12px;
}
.sk-t-team-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 20px;
  margin-top: 20px;
}
.sk-t-project-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 6px 15px;
  padding: 15px 0;
  border-bottom: 1px solid var(--tpl-line);
}
.sk-t-project-row:last-child {
  border: 0;
  padding-bottom: 0;
}
.sk-t-project-row strong {
  font-size: 11px;
  font-weight: 550;
  display: block;
}
.sk-t-project-row > div > span {
  font-size: 9px;
  color: var(--tpl-muted);
  display: block;
  margin-top: 4px;
}
.sk-t-project-row > span {
  font-size: 10px;
  color: var(--tpl-muted);
}
.sk-t-project-row > .sk-t-meter {
  grid-column: 1/-1;
  margin-top: 3px;
}
.sk-t-team-person {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-block: 12px;
  border-bottom: 1px solid var(--tpl-line);
}
.sk-t-team-person:last-child {
  border: 0;
  padding-bottom: 0;
}
.sk-t-team-person strong {
  font-size: 11px;
  display: block;
  font-weight: 550;
}
.sk-t-team-person > div > span {
  font-size: 9px;
  color: var(--tpl-muted);
  display: block;
  margin-top: 3px;
}
.sk-t-team-person > .sk-t-status-dot {
  margin-left: auto;
  width: 4px;
  height: 4px;
}
.sk-t-pinned-projects {
  margin-top: 24px;
  font-size: 10px;
}
.sk-t-pinned-projects > button {
  display: flex;
  align-items: center;
  gap: 12px;
  background: none;
  border: 0;
  width: 100%;
  padding: 10px 13px;
  color: var(--tpl-muted);
}
.sk-t-pinned-projects > button > span:last-child {
  margin-left: auto;
}
.sk-t-pinned-projects > div {
  display: grid;
  margin: 8px 0 0 22px;
  border-left: 1px solid var(--tpl-line);
  padding-left: 20px;
  gap: 15px;
  color: var(--tpl-muted);
}
@keyframes sk-t-marquee {
  to {
    transform: translateX(calc(-100% - 16px));
  }
}
@keyframes sk-t-float {
  50% {
    transform: translateY(-8px) rotate(1deg);
  }
}
