/* Existing Customize control retained. */
.tpl-customizer {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 110;
  color: var(--tpl-ink);
}

.tpl-customizer-trigger {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  min-height: 44px;
  padding: 5px 12px 5px 5px;
  border: 1px solid var(--tpl-line);
  border-radius: 9px;
  color: var(--tpl-ink);
  background: var(--tpl-raised);
  box-shadow:
    inset 0 1px 0 var(--tpl-highlight),
    0 3px 0 var(--tpl-line),
    0 9px 24px var(--tpl-shadow);
  font-size: 12px;
  font-weight: 650;
  cursor: pointer;
}

.tpl-customizer-trigger-art {
  position: relative;
  width: 31px;
  height: 31px;
  display: block;
  background: var(--tpl-well);
  border: 1px solid var(--tpl-line);
  border-radius: 6px;
  box-shadow: inset 0 2px 3px var(--tpl-shadow);
}

.tpl-customizer-trigger-art i {
  position: absolute;
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--tpl-accent);
  top: 10px;
  left: 10px;
  box-shadow: 0 1px 0 #0004;
}

.tpl-customizer-trigger-art i:nth-child(2) {
  background: var(--tpl-panel);
  left: 4px;
  top: 4px;
}
.tpl-customizer-trigger-art i:nth-child(3) {
  background: var(--tpl-secondary);
  left: 16px;
  top: 17px;
}

.tpl-customizer-panel {
  position: absolute;
  right: 0;
  bottom: 58px;
  width: min(370px, calc(100vw - 28px));
  max-height: min(650px, calc(100vh - 88px));
  overflow-y: auto;
  padding: 22px;
  border-radius: 13px;
  border: 1px solid var(--tpl-line);
  background: var(--tpl-raised);
  box-shadow:
    inset 0 2px 0 var(--tpl-highlight),
    0 4px 0 var(--tpl-line),
    0 20px 48px var(--tpl-shadow);
}

.tpl-customizer-panel[hidden] {
  display: none;
}
.tpl-customizer-heading {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 12px;
}
.tpl-customizer-heading span,
.tpl-customizer-mode > span {
  color: var(--tpl-muted);
  font:
    600 9px var(--font-geist-mono),
    monospace;
  letter-spacing: 0.14em;
}
.tpl-customizer-heading h2 {
  margin: 7px 0 0;
  color: var(--tpl-ink);
  font-size: 25px;
  letter-spacing: -0.06em;
  line-height: 1.1;
}
.tpl-customizer-heading button {
  width: 29px;
  height: 29px;
  border: 1px solid var(--tpl-line);
  border-radius: 5px;
  color: var(--tpl-ink);
  background: var(--tpl-panel);
  font-size: 20px;
  cursor: pointer;
}
.tpl-customizer-panel > p {
  color: var(--tpl-muted);
  font-size: 11px;
  line-height: 1.55;
  margin: 10px 0 19px;
}
.tpl-customizer-palettes {
  display: grid;
  gap: 8px;
}
.tpl-palette-option {
  display: flex;
  align-items: center;
  gap: 11px;
  width: 100%;
  padding: 7px;
  border: 1px solid var(--tpl-line);
  border-radius: 8px;
  text-align: left;
  color: var(--tpl-ink);
  background: var(--tpl-panel);
  cursor: pointer;
}
.tpl-palette-option[aria-pressed="true"] {
  border-color: var(--tpl-accent);
  box-shadow:
    0 0 0 1px var(--tpl-accent),
    inset 0 1px var(--tpl-highlight);
}
.tpl-palette-specimen {
  width: 62px;
  height: 47px;
  position: relative;
  flex: none;
  border: 1px solid;
  border-radius: 5px;
  overflow: hidden;
}
.tpl-palette-specimen i {
  position: absolute;
  display: block;
}
.tpl-palette-specimen i:nth-child(1) {
  inset: 11px 8px 7px;
  border: 1px solid;
  border-radius: 3px;
  box-shadow: 0 2px 0 #0002;
}
.tpl-palette-specimen i:nth-child(2) {
  width: 21px;
  height: 7px;
  left: 15px;
  top: 19px;
  border-radius: 2px;
}
.tpl-palette-specimen i:nth-child(3) {
  width: 8px;
  height: 8px;
  right: 14px;
  top: 18px;
  border-radius: 50%;
}
.tpl-palette-copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}
.tpl-palette-copy strong {
  font-size: 12px;
}
.tpl-palette-copy small {
  color: var(--tpl-muted);
  font-size: 10px;
  line-height: 1.3;
}
.tpl-palette-check {
  margin-left: auto;
  color: var(--tpl-accent);
  font-size: 15px;
}
.tpl-customizer-mode {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  margin-top: 20px;
}
.tpl-customizer-mode-control {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--tpl-ink);
  font-size: 11px;
}
.tpl-customizer-footer {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  border-top: 1px solid var(--tpl-line);
  padding-top: 16px;
  margin-top: 18px;
  font-size: 10px;
}
.tpl-customizer-footer button {
  border: 0;
  padding: 0;
  color: var(--tpl-muted);
  background: none;
  cursor: pointer;
}
.tpl-customizer-footer a {
