}
.sk-template .tpl-customizer {
  z-index: 80;
  right: 20px;
  bottom: 20px;
}
.sk-template .tpl-customizer-panel {
  max-height: calc(100dvh - 110px);
  overflow-y: auto;
}
.sk-template .tpl-customizer-trigger {
  min-height: 44px;
}
.sk-template .tpl-customizer-heading h2 {
