}
/* Scope the host site's legacy tokens without changing its original stylesheet. */
.sk-template {
  --surface: var(--tpl-panel);
  --surface-raised: var(--tpl-raised);
  --well: var(--tpl-well);
  --base: var(--tpl-well);
  --edge: var(--tpl-line);
  --highlight: var(--tpl-highlight);
  --shadow: var(--tpl-shadow);
  --ink: var(--tpl-ink);
  --site-muted: var(--tpl-muted);
  --accent: var(--tpl-accent);
  --accent-ink: var(--tpl-accent-ink);
  --accent-bright: var(--sk-accent-bright);
  --accent-base: var(--sk-accent-base);
}
